-- RT-2.25: a structured strategic reading, anchored to the published T1 commercial outcome.
insert into public.workbench_tool_revisions (code, version, status, title, methodology_outcome_id, spec)
select 'swot_strategic_reading_v1', 1, 'published', 'Leitura estratégica SWOT', outcome.id,
'{"fields":[{"code":"strengths","label":"Forças","kind":"entries","required":true,"min_entries":1,"max_entries":12,"entry_fields":[{"code":"insight","label":"Força observável","required":true,"max_length":300},{"code":"evidence","label":"Evidência ou exemplo","required":true,"max_length":600}]},{"code":"weaknesses","label":"Fraquezas","kind":"entries","required":true,"min_entries":1,"max_entries":12,"entry_fields":[{"code":"insight","label":"Fragilidade observável","required":true,"max_length":300},{"code":"evidence","label":"Evidência ou exemplo","required":true,"max_length":600}]},{"code":"opportunities","label":"Oportunidades","kind":"entries","required":true,"min_entries":1,"max_entries":12,"entry_fields":[{"code":"insight","label":"Oportunidade concreta","required":true,"max_length":300},{"code":"evidence","label":"Sinal ou fonte","required":true,"max_length":600}]},{"code":"threats","label":"Ameaças","kind":"entries","required":true,"min_entries":1,"max_entries":12,"entry_fields":[{"code":"insight","label":"Risco externo","required":true,"max_length":300},{"code":"evidence","label":"Sinal ou fonte","required":true,"max_length":600}]}],"analysis_dimensions":["ambiente interno","ambiente externo","prioridades estratégicas","riscos"],"export_formats":["pdf","xlsx"]}'::jsonb
from public.development_outcomes outcome where outcome.code = 't1_marketing_sales_funnel_value'
on conflict (code, version) do nothing;
